const cheerio = require('cheerio');
const html = $json.html || $json.body || '';
const url = $json.url;
const $ = cheerio.load(html);

const metaTags = {
  title: $('title').text() || undefined,
  description: $('meta[name="description"]').attr('content'),
  ogTitle: $('meta[property="og:title"]').attr('content'),
  ogDescription: $('meta[property="og:description"]').attr('content'),
  ogImage: $('meta[property="og:image"]').attr('content'),
  ogType: $('meta[property="og:type"]').attr('content'),
  twitterTitle: $('meta[name="twitter:title"]').attr('content'),
  twitterDescription: $('meta[name="twitter:description"]').attr('content'),
  twitterImage: $('meta[name="twitter:image"]').attr('content'),
  canonical: $('link[rel="canonical"]').attr('href'),
  robots: $('meta[name="robots"]').attr('content'),
  charset: $('meta[charset]').attr('charset'),
  viewport: $('meta[name="viewport"]').attr('content'),
  keywords: $('meta[name="keywords"]').attr('content'),
  author: $('meta[name="author"]').attr('content')
};

const headings = [];
$('h1, h2, h3').each((_, el) => {
  const text = $(el).text().trim();
  if (text) {
    headings.push({ level: parseInt(el.name[1]), text: text });
  }
});

const links = [];
const urlObj = new URL(url);
const baseDomain = urlObj.hostname;
$('a[href]').each((_, el) => {
  const href = $(el).attr('href');
  const text = $(el).text().trim();
  if (!href) return;
  let isInternal = false;
  try {
    const linkUrl = new URL(href, url);
    isInternal = linkUrl.hostname === baseDomain;
  } catch (e) {
    isInternal = true;
  }
  links.push({ href: href, text: text, isInternal: isInternal });
});

const images = [];
$('img').each((_, el) => {
  images.push({
    src: $(el).attr('src'),
    alt: $(el).attr('alt'),
    hasWidth: $(el).attr('width') ? true : false,
    hasHeight: $(el).attr('height') ? true : false
  });
});

return { metaTags, headings, links, images, charset: metaTags.charset || 'UTF-8', htmlLength: html.length };

const cheerio = require('cheerio');
const html = $json.html || '';
const $ = cheerio.load(html);
const schemaMarkups = [];

$('script[type="application/ld+json"]').each((_, el) => {
  try {
    const jsonld = JSON.parse($(el).html() || '{}');
    const items = Array.isArray(jsonld) ? jsonld : [jsonld];
    items.forEach(item => {
      if (item['@type']) {
        schemaMarkups.push({ type: item['@type'], properties: item });
      }
    });
  } catch (e) {}
});

$('[itemtype]').each((_, el) => {
  const $el = $(el);
  const itemtype = $el.attr('itemtype');
  const properties = {};
  $el.find('[itemprop]').each((_, propEl) => {
    const propName = $(propEl).attr('itemprop');
    const propValue = $(propEl).attr('content') || $(propEl).text();
    properties[propName] = propValue;
  });
  if (itemtype) {
    schemaMarkups.push({ type: itemtype.split('/').pop(), properties });
  }
});

return { schemaMarkup: schemaMarkups.length > 0 ? schemaMarkups : null, schemaCount: schemaMarkups.length };

const html = $json.html || '';
const lower = html.toLowerCase();
const cmsSignatures = {
  'WordPress': ['wordpress', '/wp-content/', '/wp-includes/', 'wp-json'],
  'Shopify': ['shopify', 'cdn/shop/', 'myshopify'],
  'Wix': ['wix', 'wix-container', '_wix'],
  'Blogger': ['blogger', 'blogspot.com'],
  'Medium': ['medium', 'medium.com'],
  'Drupal': ['drupal', '/sites/all/'],
  'Cafe24': ['cafe24', 'www.cafe24.com'],
  'Godosmall': ['godo', 'godomall'],
  'Imweb': ['imweb', 'imweb.co.kr']
};

for (const [cms, keywords] of Object.entries(cmsSignatures)) {
  if (keywords.some(kw => lower.includes(kw))) {
    return { detectedCms: cms };
  }
}
return { detectedCms: null };

const result = {
  company_id: $json.company_id,
  url: $json.url,
  crawled_at: new Date().toISOString(),
  status: 'success',
  meta_tags: $json.metaTags || {},
  headings: $json.headings || [],
  links: $json.links || [],
  images: $json.images || [],
  schema_markup: $json.schemaMarkup,
  robots_txt: null,
  sitemap_info: null,
  performance_metrics: null,
  detected_cms: $json.detectedCms,
  is_latest: true,
  html_truncated: ($json.htmlLength || 0) > 5242880
};

if (!result.html_truncated && $json.html) {
  result.raw_html = $json.html;
} else if ($json.html) {
  result.raw_html = $json.html.substring(0, 5242880);
}

return result;

